<template><StatePanel v-if="pending" kind="loading" title="Loading services" message="Retrieving bookable services." /><StatePanel v-else-if="error || !identity" kind="error" title="Services unavailable" message="This business storefront could not be loaded." /><StorefrontFrame v-else :identity="identity" :navigation="navigation" :base="base"><PageHeader title="Services" description="Choose a service, then see staff availability or scheduled group sessions in your timezone." /><div v-if="services?.length" class="mt-8 border-y bg-card"><article v-for="service in services" :key="service.public_id" class="resource-row sm:grid-cols-[minmax(0,1fr)_auto_auto] sm:items-center"><div><h2 class="font-bold">{{ service.name }}</h2><p class="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{{ service.summary }}</p></div><span class="font-bold">{{ money(service.base_price) }}</span><ButtonAnchor  :href="`${base}/services/${service.slug}`">View times</ButtonAnchor></article></div><StatePanel v-else class="mt-8" title="No services published" message="This business has not published bookable services yet." /></StorefrontFrame></template>
<script setup>
definePageMeta({ layout: 'storefront' }); const route = useRoute(); const { identity, navigation, pending, error, baseURL, siteBase: base } = useStorefrontContext(route.params.slug); const { data: services } = useAsyncData(`services:${route.params.slug}`, () => $fetch(`public/${route.params.slug}/catalog/`, { baseURL, query: { type: 'service' } })); const money = (value) => new Intl.NumberFormat('en-PH', { style: 'currency', currency: identity.value?.currency || 'PHP' }).format(Number(value || 0))
</script>
